 if(a==='self-good'||a==='self-redo'){s.success=a==='self-good';s.feedback=s.success?'Self assessed: the response meets the model’s key points.':'Add or improve the missing points in your explanation.';render();return;}
 if(a.startsWith('ink-')){if(['ink-pointer','ink-pen','ink-highlighter','ink-line','ink-eraser'].includes(a))state.pen=a.slice(4);if(a==='ink-color'){state.color=el.dataset.color;if(!['pen','highlighter','line'].includes(state.pen))state.pen='pen';}if(a==='ink-undo'||a==='ink-clear'){if(state.sixScreen){if(a==='ink-undo')undoSixInk();else{const qs=visibleSixQuestions();rememberSixInk(qs);qs.forEach(q=>qa(q).ink=[]);}}else modelQs.forEach((q,i)=>{if(state.focus<0||i===state.focus){const s=qa(q);if(a==='ink-undo')s.ink.pop();else s.ink=[];}});}render();return;}
 if(a==='mixed-practice'){state.practiceSkill=null;state.practiceQs=[];generatePractice();route('practice');if(state.view==='practice')render();return;}
 if(a==='practice-topics-all'||a==='practice-topics-none'){state.practiceIds=a==='practice-topics-all'?SKILLS.map(s=>s.id):[];render();return;}
